// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        c.initialize();

        address alloSettingsAddr = address(0x1234);
        c.updateAlloSettings(alloSettingsAddr);

        address operator = address(0x5678);
        vm.prank(c.owner());

        address impl = address(0x9ABC);
        vm.prank(c.owner());
        c.updateRoundImplementation(payable(impl));


        address zero = address(0);
        vm.prank(c.owner());
        (bool success, ) = address(c).call(abi.encodeWithSignature("updateRoundImplementation(address)", zero));


        vm.prank(c.owner());
        (bool ok, ) = address(c).call(abi.encodeWithSignature("updateRoundImplementation(address)", zero));

        address currentImpl = c.roundImplementation();

        assertTrue(currentImpl == impl, "Reference keeps non-zero impl; bug sets to zero");
    }
}
